REPO_ROOT = os.path.dirname(os.path.abspath(__file__))
AGENTS_DIR = os.path.join(REPO_ROOT, "Agents")
ABILITIES_DIR = os.path.join(REPO_ROOT, "Abilities")


def download(url, dest_path):
    if os.path.exists(dest_path):
        print("  skip (already exists): " + os.path.relpath(dest_path, REPO_ROOT))
        return
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=20) as resp, open(dest_path, "wb") as out:
            out.write(resp.read())
        print("  saved: " + os.path.relpath(dest_path, REPO_ROOT))
    except Exception as e:
        print("  FAILED (" + url + "): " + str(e))


def main():
    os.makedirs(AGENTS_DIR, exist_ok=True)
    os.makedirs(ABILITIES_DIR, exist_ok=True)

    for agent in AGENTS:
        display_name = agent["name"]
        # Matches the app's own naming: Agents/<Capitalized-id>.png
        file_name = agent["id"][0].upper() + agent["id"][1:] + ".png"
        print(display_name + ":")

        download(agent["icon"], os.path.join(AGENTS_DIR, file_name))

        agent_ability_dir = os.path.join(ABILITIES_DIR, agent["id"][0].upper() + agent["id"][1:])
        os.makedirs(agent_ability_dir, exist_ok=True)
        for ability in agent["abilities"]:
            key = ability["key"]  # Q / E / C / X / P
            download(ability["icon"], os.path.join(agent_ability_dir, key + ".png"))

    print("")
    print("Done. Agent icons are in Agents/, ability icons are in Abilities/<Agent>/<Q|E|C|X|P>.png")


if __name__ == "__main__":
    main()
